import re
import time
import logging
import mace
from datetime import datetime


class LogCollector(object):

    _MAX_MILLISEC_TO_WAIT = 100
    _MAX_DURATION_FOR_COLLECTING_LOG = 1200

    def __init__(self, device, **kwargs):
        self._device = device
        self._itemset = self._subscribe_log(**kwargs)
        self._latest_end_datetime = None
        self._last_log_items = None
        self._start_timestamp = None

    def set_start_timestamp(self, timestamp):
        self._start_timestamp = timestamp

    def _subscribe_log(self, **kwargs):
        pass

    def collect_log_by_duration(self, begin=None, end=None, last_log_items=None):
        self._set_log_time_range(begin, end)
        self._last_log_items = last_log_items
        return self._collect_log_by_duration()

    def collect_log_until(self, expected_content, timeout, begin=None, last_log_items=None):
        self._set_log_time_range(begin=begin, end=None)
        self._last_log_items = last_log_items
        return self._collect_log_until(expected_content, timeout)

    def _set_log_time_range(self, begin, end):
        if begin:
            self._itemset.set_time_range(begin)
        elif self._start_timestamp:
            self._itemset.set_time_range(self._start_timestamp)

        if end:
            self._itemset.set_time_range(end=end)

    def _collect_log_by_duration(self):
        log_items = []
        start = time.time()
        end = start + self._MAX_DURATION_FOR_COLLECTING_LOG
        while time.time() < end:
            log_item = self._itemset.get_next_item(self._MAX_MILLISEC_TO_WAIT)
            if not log_item:
                break
            if self._is_last_log_item(log_item):
                continue
            log_items.append(log_item)
        return log_items

    def _collect_log_until(self, expect_content, timeout):
        log_items = []
        start = time.time()
        end = start + timeout
        while time.time() < end:
            log_item = self._itemset.get_next_item(self._MAX_MILLISEC_TO_WAIT)
            if log_item:
                if self._is_last_log_item(log_item):
                    continue
                log_items.append(log_item)
                if self._wait_message_until(log_item, expect_content):
                    break
        return log_items

    def _is_last_log_item(self, log_item):
        if self._last_log_items:
            for history_log_item in reversed(self._last_log_items):
                if str(history_log_item.timestamp) != str(log_item.timestamp):
                    break
                if hasattr(history_log_item, "message") and history_log_item.message == log_item.message:
                    return True
        return False

    def _wait_message_until(self, log_item, expect_content):
        return True if re.search(expect_content, log_item.message) else False


class OTATextMessage(LogCollector):

    def __init__(self, device, **kwargs):
        super(OTATextMessage, self).__init__(device, **kwargs)

    def _subscribe_log(self):
        itemset = mace.create_itemset(self._device)
        itemset.subscribe_ota()
        return itemset


class OTAJsonMessage(OTATextMessage):

    def __init__(self, device, **kwargs):
        super(OTAJsonMessage, self).__init__(device, **kwargs)

    def _wait_message_until(self, log_item, expect_content):
        return True if re.search(expect_content, str(log_item.ota_json)) else False


class SystemTrace(LogCollector):

    def __init__(self, device, **kwargs):
        super(SystemTrace, self).__init__(device, **kwargs)

    def _subscribe_log(self):
        itemset = mace.create_itemset(self._device)
        itemset.subscribe_sys()
        return itemset


class PSTrace(LogCollector):

    def __init__(self, device, **kwargs):
        super(PSTrace, self).__init__(device, **kwargs)

    def _subscribe_log(self, traceids, core, sim_index, module):
        itemset = mace.create_itemset(self._device)
        itemset.subscribe_ps(traceids, core=core, sim_index=sim_index, module=module)
        return itemset


class RawString(LogCollector):

    def __init__(self, device, **kwargs):
        super(RawString, self).__init__(device, **kwargs)

    def _subscribe_log(self, strings_to_search, core, module):
        itemset = mace.create_itemset(self._device)
        itemset.subscribe_raw_string(strings_to_search=strings_to_search, core=core, module=module)
        return itemset


class Filter(object):

    def __init__(self, **kwargs):
        self._filter_conditions = kwargs

    def should_match(self, log_items):
        filted_items = []
        for log_item in log_items:
            for attribute, value in self._filter_conditions.items():
                if hasattr(log_item) and str(getattr(log_item, attribute)) == value:
                    filted_items.append(log_item)
        return filted_items


class MessageFormator(object):

    def __init__(self, *args):
        self._ITEM_ATTRIBUTE_LIST = args if args else ["timestamp", "message"]

    def format(self, log_items):
        message_list = []
        for log_item in log_items:
            attribute_values = [str(getattr(log_item, attribute)) for attribute in self._ITEM_ATTRIBUTE_LIST]
            message_list.append('  '.join(attribute_values))
        return message_list


class CollectorAliasStore(object):

    _STORE = {}

    def set_last_log_by_alias(self, alias_name, log_items=None):
        if log_items:
            self._STORE[alias_name] = log_items

    def get_last_timestamp_log_items_by_alias(self, alias_name):
        if alias_name not in self._STORE:
            return None, None

        log_items = self._STORE[alias_name]
        return log_items[-1].timestamp, log_items

    def clear_store(self):
        self._STORE = {}


class LogCollectorFacade(object):

    def __init__(self, device):
        self._device = device
        self._alias_store = CollectorAliasStore()
        self._default_message_formator = MessageFormator()
        self._start_timestamp = None

    def set_start_timestamp(self, timestamp=None):
        self._start_timestamp = timestamp if timestamp else self._get_current_timestamp()
        logging.info("set start timestamp {}".format(str(self._start_timestamp)))

    def _get_current_timestamp(self):
        return datetime.now()

    def read_ota_text_message_until(self, alias_name, expected_content, timeout=60,
                                    filter=None, message_formator=None):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = OTATextMessage(self._device)
        return self._read_log_until(alias_name, expected_content, timeout, filter, message_formator)

    def read_latest_ota_text_message(self, alias_name, filter=None, message_formator=None):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = OTATextMessage(self._device)
        return self._read_latest_log(alias_name, filter, message_formator)

    def read_ota_json_message_until(self, alias_name, expected_content, timeout=60,
                                    filter=None, message_formator=MessageFormator("timestamp", "ota_json")):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = OTAJsonMessage(self._device)
        return self._read_log_until(alias_name, expected_content, timeout, filter, message_formator)

    def read_latest_ota_json_message(self, alias_name,
                                     filter=None, message_formator=MessageFormator("timestamp", "ota_json")):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = OTAJsonMessage(self._device)
        return self._read_latest_log(alias_name, filter, message_formator)

    def read_system_trace_until(self, alias_name, expected_content, timeout=60,
                                filter=None, message_formator=None):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = SystemTrace(self._device)
        return self._read_log_until(alias_name, expected_content, timeout, filter, message_formator)

    def read_latest_system_trace(self, alias_name, filter=None, message_formator=None):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = SystemTrace(self._device)
        return self._read_latest_log(alias_name, filter, message_formator)

    def read_ps_trace_until(self, alias_name, expected_content, timeout=60,
                            filter=None, message_formator=None,
                            traceids="", core=-1, sim_index=-1, module=None):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = PSTrace(self._device,
                                          traceids=traceids, core=core, sim_index=sim_index, module=module)
        return self._read_log_until(alias_name, expected_content, timeout, filter, message_formator)

    def read_latest_ps_trace(self, alias_name, filter=None, message_formator=None,
                             traceids="", core=-1, sim_index=-1, module=None):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = PSTrace(self._device,
                                          traceids=traceids, core=core, sim_index=sim_index, module=module)
        return self._read_latest_log(alias_name, filter, message_formator)

    def read_raw_string_until(self, alias_name, expected_content, timeout=60,
                              filter=None, message_formator=None,
                              strings_to_search="", core=-1, module=-1):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = RawString(self._device,
                                            strings_to_search=strings_to_search, core=core, module=module)
        return self._read_log_until(alias_name, expected_content, timeout, filter, message_formator)

    def read_latest_raw_string(self, alias_name, filter=None, message_formator=None,
                               strings_to_search="", core=-1, module=-1):
        message_formator = message_formator if message_formator else self._default_message_formator
        self._message_collector = RawString(self._device,
                                            strings_to_search=strings_to_search, core=core, module=module)
        return self._read_latest_log(alias_name, filter, message_formator)

    def _read_log_until(self, alias_name, expected_content, timeout, filter, message_formator):
        begin, last_log_items = self._alias_store.get_last_timestamp_log_items_by_alias(alias_name)
        begin = begin if begin else self._start_timestamp
        logging.info("read_log_until alias_name={} begin={}".format(alias_name, str(begin)))
        log_items = self._message_collector.collect_log_until(expected_content=expected_content, timeout=timeout,
                                                              begin=begin, last_log_items=last_log_items)
        self._alias_store.set_last_log_by_alias(alias_name, log_items=log_items)
        return self._remove_overlap_and_get_log_records(last_log_items, log_items, filter, message_formator)

    def _read_latest_log(self, alias_name, filter, message_formator):
        begin, last_log_items = self._alias_store.get_last_timestamp_log_items_by_alias(alias_name)
        begin = begin if begin else self._start_timestamp
        logging.info("read_latest_log alias_name={} begin={}".format(alias_name, str(begin)))
        log_items = self._message_collector.collect_log_by_duration(begin=begin, end=None,
                                                                    last_log_items=last_log_items)
        self._alias_store.set_last_log_by_alias(alias_name, log_items=log_items)
        return self._remove_overlap_and_get_log_records(last_log_items, log_items, filter, message_formator)

    def _remove_overlap_and_get_log_records(self, previous_log_items, current_log_items, filter, message_formator):
        previous_log_records = []
        if previous_log_items:
            previous_log_records = self._apply_filter_and_message_formator(previous_log_items,
                                                                           filter,
                                                                           message_formator)

        current_log_records = self._apply_filter_and_message_formator(current_log_items, filter, message_formator)
        log_records = set(current_log_records).difference(set(previous_log_records))
        return sorted(log_records, key=current_log_records.index)

    @staticmethod
    def _apply_filter_and_message_formator(log_items, filter, message_formator):
        if filter:
            log_items = filter.should_match(log_items)

        if message_formator:
            log_items = message_formator.format(log_items)

        return log_items

    def clear_collector_alias_store(self):
        self._alias_store.clear_store()
